  if(personImage?.startsWith('person:')){const id=personImage.slice(7),person=[...people,...romancePeople,...(state.population?.residents||[])].find(p=>p.id===id);if(person)return citizenPortrait(state,person,'social-incident-portrait');}
  const scenes=[['yard','boots'],['yard',''],['market',''],['market',''],['industrial',''],['yard',''],['yard',''],['industrial',''],['yard',''],['industrial',''],['center','jacket'],['glass','jacket'],['market','bike'],['market',''],['center',''],['yard','']];
  const [district,item]=scenes[art]||scenes[0];const image=items[item]||transport[item]||'';
