export function modal(s,mini,dialogueId=null,dialogueResult=null,travelId=null,citizenId=null,citizenPane='life') {
  if(s.death)return `<div class="modal-scrim"><div class="modal decision-modal death-modal"><div class="death-art" style="background-image:linear-gradient(0deg,#172020,transparent),url('${backgrounds[s.district]}')"></div><span class="eyebrow">ЖИЗНЬ ИДЁТ СВОИМ ЧЕРЕДОМ</span><h2>ПОСЛЕДНИЙ ДЕНЬ</h2><p>${esc(s.death.cause)}. Тебе было ${s.death.age} лет. Прожито ${s.death.day} игровых дней. Капитал: ${money(netWorth(s))}.</p><button class="primary big" data-action="restart-after-death">НАЧАТЬ НОВУЮ ЖИЗНЬ</button></div></div>`;
  if(mini)return `<div class="modal-scrim"><div class="modal mini-modal" style="--mini-bg:url('${backgrounds[mini.job.district]}')">${mini.render()}</div></div>`;
  if(s.casinoTable)return casinoTableModal(s);
  if(s.romance?.conflict)return romanceConflictModal(s);
  if(s.recentIncident)return incidentModal(s);
  if(travelId)return travelModal(s,travelId);
  if(s.jailDays>0)return `<div class="modal-scrim"><div class="modal decision-modal jail-modal"><div class="modal-emblem">ЗАДЕРЖАНИЕ</div><span class="eyebrow">ИЗОЛЯТОР / БЕЗ ВИДА НА ГОРОД</span><h2>ТВОЙ СРОК</h2><p>Осталось ${s.jailDays} дн. В заключении время проходит автоматически: заработка и расходов нет, здоровье и настроение страдают.</p><div class="jail-count">${s.jailDays} <small>ДНЕЙ ДО СВОБОДЫ</small></div><button class="primary big" data-action="serve">ОТСИДЕТЬ СРОК</button><div class="modal-foot">ПОСЛЕ ВЫХОДА ПРОВЕРЬ ДНЕВНИК</div></div></div>`;
  if(dialogueId)return dialogueModal(s,dialogueId,dialogueResult);
  if(!s.pending)return citizenId?citizenModal(s,citizenId,citizenPane):'';
  const data=events.find(x=>x.id===s.pending.id);
  if(!data)return '';
  return `<div class="modal-scrim"><div class="modal decision-modal"><div class="modal-emblem">СОБЫТИЕ</div><span class="eyebrow">ГОРОД НЕ СПРАШИВАЕТ</span><h2>${esc(data.title)}</h2><p>${esc(data.text)}</p><div class="decision-options">${data.choices.map((c,i)=>`<button data-choice="${i}" ${c.cost>s.money?'disabled':''}><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(c.text)}</strong>${c.cost?`<small>− ${money(c.cost)}</small>`:''}</button>`).join('')}</div><div class="modal-foot">РЕШЕНИЕ ОСТАНЕТСЯ С ТОБОЙ</div></div></div>`;
}
export function menuModal(s) {return `<div class="modal-scrim dismissable"><div class="modal menu-modal"><button class="close-modal" data-action="close-menu">×</button><span class="eyebrow">ТЕХНИЧЕСКАЯ ПАПКА</span><h2>Сохранение</h2><p>Прогресс сохраняется в этом браузере после каждого действия. Можно перенести его файлом.</p><div class="menu-actions">${b('СОХРАНИТЬ СЕЙЧАС','save','','','primary')}${b('ЭКСПОРТ JSON','export')}${b('ИМПОРТ JSON','import')}${b('НОВАЯ ИГРА','reset')}</div><p class="menu-note">Версия сохранения: ${s.version}. Время идёт только во время игровых действий.</p><input id="import-file" type="file" accept="application/json,.json" hidden></div></div>`;}





